SELECT api_code,batch_no,sync_file_id,user_key,fail_msg,release_time,status,status_msg,extend
FROM b_tcyr_cpa_fail_data
WHERE is_del = 1

    AND id >=#{minId}


    AND sync_file_id = #{syncFileId}

order by id asc limit 2000;

SELECT max(id)
FROM b_tcyr_cpa_fail_data
WHERE sync_file_id = #{syncFileId}
  and is_del = 1;

SELECT min(id)
FROM b_tcyr_cpa_fail_data
WHERE sync_file_id = #{syncFileId}
  and is_del = 1;

SELECT api_code,batch_no,sync_file_id,user_key,fail_msg,release_time,status,status_msg,extend
FROM b_tcyr_cpa_fail_data
WHERE is_del = 1

    AND id >= #{startId}


    AND id <= #{endId}


    AND sync_file_id = #{syncFileId}

order by id asc limit #{batchSize};
